# Model a AST structure using clang

# standard approach on Ubuntu 24.04 is to use python bindings for libclang.
# sudo apt install clang libclang-dev python3-clang python3-pip

# Below code is generated by Gemini and needs to be tested

import sys
from clang.cindex import Index, CursorKind, Config

Config.set_library_path("/usr/lib/llvm-14/lib")

def traverse_ast(node, indent=0):
    """
    Recursively scans the Abstract Syntax Tree (AST) nodes and flags structure metrics.
    """
    # Filter nodes to reduce baseline compiler header noise (focus solely on our file)
    if node.location.file and node.location.file.name == "main.cpp":
        # Format the visual layout mapping
        print(f"{'  ' * indent}▸ Node: {node.kind.name} | Spelled: '{node.spelling}'")
        
        # Highlight crucial QA focal targets
        if node.kind == CursorKind.CLASS_DECL:
            print(f"{'  ' * (indent + 1)}[QA Flag] Found Target Class Model: {node.spelling}")
        elif node.kind == CursorKind.CXX_METHOD:
            print(f"{'  ' * (indent + 1)}[QA Flag] Streaming Logic Pipeline Element: {node.spelling}()")
        elif node.kind == CursorKind.CALL_EXPR:
            print(f"{'  ' * (indent + 1)}[QA Flag] Subsystem Interaction API Invocation: {node.spelling}()")

    # Recurse down matching leaf tokens
    for child in node.get_children():
        traverse_ast(child, indent + 1)

def main():
    if len(sys.argv) < 2:
        print("Usage: python3 parse_ast.py <source_file.cpp>")
        sys.exit(1)

    source_file = sys.argv[1]
    index = Index.create()
    
    # QA Architecture Tip: Pass system headers + compilation link flags down to libclang parse array
    # If using system zlib, pass compiler lookup arguments identical to standard compiler invocation strings.
    compilation_arguments = ['-std=c++17', '-lz']
    
    print(f"Parsing AST architecture for: {source_file}...")
    translation_unit = index.parse(source_file, args=compilation_arguments)
    
    # Diagnostic error mapping loops
    diagnostics = list(translation_unit.diagnostics)
    if diagnostics:
        print("\n--- Parser Compiler Warning/Error Flags ---")
        for diag in diagnostics:
            print(f"[{diag.severity}] {diag.spelling} at line {diag.location.line}")
        print("-------------------------------------------\n")

    print("\n--- Modeled AST Tree Output Representation ---")
    traverse_ast(translation_unit.cursor)

if __name__ == "__main__":
    main()
